def normalize_laboratory_data(apps, schema_editor):
    AnalyseDemandee = apps.get_model("laboratoire", "AnalyseDemandee")
    HistoriqueAction = apps.get_model("laboratoire", "HistoriqueAction")
    ParametresLaboratoire = apps.get_model("laboratoire", "ParametresLaboratoire")
    Prelevement = apps.get_model("laboratoire", "Prelevement")
    Resultat = apps.get_model("laboratoire", "Resultat")

    settings, _ = ParametresLaboratoire.objects.get_or_create(pk=1)
    reasons = list(settings.motifs_rejet or [])
    for reason in Prelevement.objects.filter(statut="REJETE").values_list(
        "motif_rejet", flat=True,
    ).distinct():
        if reason and reason not in reasons:
            reasons.append(reason)
    for reason in ("Étiquette illisible", "Autre"):
        if reason not in reasons:
            reasons.append(reason)
    settings.motifs_rejet = reasons
    settings.save(update_fields=["motifs_rejet"])

    for prelevement in Prelevement.objects.select_related("demande").all().iterator():
        if prelevement.statut == "A_EFFECTUER":
            prelevement.date_prelevement = None
            prelevement.date_reception = None
        prelevement.date_creation = (
            prelevement.date_prelevement
            or prelevement.date_reception
            or prelevement.demande.date_demande
        )
        prelevement.save(update_fields=[
            "date_creation", "date_prelevement", "date_reception",
        ])

    for analyse in AnalyseDemandee.objects.all().iterator():
        resultats = list(
            Resultat.objects.filter(analyse_demandee_id=analyse.pk)
            .order_by("-date_modification", "-pk")
        )
        if not resultats:
            continue
        latest = resultats[0]
        if latest.prelevement_id:
            analyse.prelevement_id = latest.prelevement_id
            analyse.save(update_fields=["prelevement"])
        for duplicate in resultats[1:]:
            HistoriqueAction.objects.create(
                utilisateur_id=duplicate.saisi_par_id,
                type_action="RESULTAT_FUSIONNE_MIGRATION",
                objet_concerne="Resultat",
                objet_id=duplicate.pk,
                details={
                    "raison": "Un seul résultat est désormais autorisé par analyse.",
                    "resultat_conserve_id": latest.pk,
                    "valeur": duplicate.valeur,
                    "unite": duplicate.unite,
                    "valeur_reference": duplicate.valeur_reference,
                    "interpretation": duplicate.interpretation,
                    "observation": duplicate.observation,
                    "statut": duplicate.statut,
                    "prelevement_id": duplicate.prelevement_id,
                },
            )
            duplicate.delete()

    for resultat in Resultat.objects.all().iterator():
        if resultat.statut not in ("EN_SAISIE", "VALIDE"):
            resultat.statut = "EN_SAISIE"
            resultat.valide_par_id = None
            resultat.date_validation = None
            resultat.save(update_fields=["statut", "valide_par", "date_validation"])


